def stack_machine(instructions):
    stack = []
    for instr in instructions:
        if isinstance(instr, tuple) and len(instr) >= 1:
            op = instr[0]
            if op == 'push':
                # push value
                if len(instr) > 1:
                    stack.append(instr[1])
                else:
                    raise ValueError("push requires a value")
            elif op == 'add':
                b = stack.pop()
                a = stack.pop()
                stack.append(a + b)
            elif op == 'multiply':
                b = stack.pop()
                a = stack.pop()
                stack.append(a * b)
            elif op == 'negate':
                a = stack.pop()
                stack.append(-a)
            else:
                raise ValueError(f"Unknown instruction {op}")
        else:
            raise ValueError(f"Invalid instruction {instr}")
    if len(stack) != 1:
        raise ValueError("Stack must contain exactly one value")
    return stack[0]

