def bencode_int(data):
    if not isinstance(data, bytes):
        raise TypeError("Input must be bytes")
    if data[0] != ord('i'):
        raise ValueError("Not an integer bencode")
    # Find the end index of 'e'
    try:
        e_index = data.index(ord('e'), 1)
    except ValueError:
        raise ValueError("Missing terminating e")
    num_str = data[1:e_index]
    # Check for sign
    if num_str.startswith(b'-'):
        sign = -1
        num_str = num_str[1:]
    elif num_str.startswith(b'+'):
        sign = 1
        num_str = num_str[1:]
    else:
        sign = 1
    # Check for leading zeros
    if len(num_str) > 1 and num_str[0] == ord('0'):
        raise ValueError("Leading zero")
    # Check for negative zero
    if sign == -1 and num_str == b'0':
        raise ValueError("Negative zero")
    # Convert to int
    try:
        value = int(num_str)
    except ValueError:
        raise ValueError("Invalid integer")
    return sign * value

