def json_pointer(obj, pointer):
    if pointer == "":
        return obj
    if not pointer.startswith("/"):
        raise ValueError("Invalid pointer")
    tokens = pointer[1:].split("/")
    for token in tokens:
        # Decode JSON Pointer escape sequences
        token = token.replace("~0", "~").replace("~1", "/")
        if isinstance(obj, dict):
            if token not in obj:
                raise KeyError(f"Key '{token}' not found")
            obj = obj[token]
        elif isinstance(obj, list):
            if not token.isdigit():
                raise ValueError(f"List index must be integer, got '{token}'")
            idx = int(token)
            if idx < 0 or idx >= len(obj):
                raise IndexError(f"List index {idx} out of range")
            obj = obj[idx]
        else:
            raise TypeError("Object must be dict or list")
    return obj

