    if n < 0:
        return False
    if n == 0 or n == 1:
        return True
    left, right = 1, n
    while left <= right:
        mid = (left + right) // 2
        sq = mid * mid
        if sq == n:
            return True
        elif sq < n:
            left = mid + 1
        else:
            right = mid - 1
    return False

